import dlantr = require( './index' );

var A = new Float64Array( 4 );
var work = new Float64Array( 2 );

dlantr( 'row-major', 'max', 'upper', 'non-unit', 2, 2, A, 2, work ); // $ExpectType number
dlantr.ndarray( 'infinity', 'lower', 'unit', 2, 2, A, 2, 1, 0, work, -1, 1 ); // $ExpectType number

dlantr( 101, 'max', 121, 131, 2, 2, A, 2, work ); // $ExpectType number
dlantr.ndarray( 'one', 122, 132, 2, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectType number

dlantr( 'bad', 'max', 'upper', 'unit', 2, 2, A, 2, work ); // $ExpectError
dlantr( 'row-major', 'M', 'upper', 'unit', 2, 2, A, 2, work ); // $ExpectError
dlantr( 'row-major', 'max', 'all', 'unit', 2, 2, A, 2, work ); // $ExpectError
dlantr( 'row-major', 'max', 'upper', 'bad', 2, 2, A, 2, work ); // $ExpectError
dlantr( 'row-major', 'max', 'upper', 'unit', 2, 2, [], 2, work ); // $ExpectError
dlantr( 'row-major', 'max', 'upper', 'unit', 2, 2, A, 2 ); // $ExpectError
dlantr.ndarray( 'bad', 'lower', 'unit', 2, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
dlantr.ndarray( 'max', 'all', 'unit', 2, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
dlantr.ndarray( 'max', 'lower', 'bad', 2, 2, A, 2, 1, 0, work, 1, 0 ); // $ExpectError
dlantr.ndarray( 'max', 'lower', 'unit', 2, 2, [], 2, 1, 0, work, 1, 0 ); // $ExpectError
